if(EditorApplication.isPlaying)throw new System.Exception("Edit only");var terrain=Terrain.activeTerrain;var changes=new System.Collections.Generic.List<object>();foreach(var f in GameObject.Find("Woodland03 - gathering grove composition").GetComponentsInChildren<MeshFilter>().Where(f=>f.name.StartsWith("BW_Woodland01_Tree"))){var m=f.sharedMesh;var v=m.vertices;var ids=m.GetTriangles(0).Distinct().ToArray();float low=ids.Min(i=>v[i].y);var ring=ids.Where(i=>v[i].y<low+.08f).Select(i=>f.transform.TransformPoint(v[i])).ToArray();float high=ring.Max(p=>p.y-terrain.SampleHeight(p)-terrain.transform.position.y);if(high>.04f){f.transform.position-=Vector3.up*(high+.015f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.transform);changes.Add(new{name=f.name,x=f.transform.position.x,z=f.transform.position.z,lowered=high+.015f});}}Physics.SyncTransforms();UnityEditor.SceneManagement.EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene());System.IO.File.WriteAllText("ArtSource/Pipeline/Review/BriarwickWoodland03/RootSeating.json",Newtonsoft.Json.JsonConvert.SerializeObject(changes,Newtonsoft.Json.Formatting.Indented));return changes;
